#!/usr/bin/env node
// INSPAND-007: CANNON inspects a source-native Iron Lung Golden Compass study.
// It never runs code generated by the model and never selects a capability.
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {readFileSync,writeFileSync,mkdtempSync,mkdirSync,renameSync,rmSync,existsSync,lstatSync,realpathSync} from 'node:fs';
import {resolve,join,dirname,basename} from 'node:path';
import {fileURLToPath} from 'node:url';

const ROOT=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const LOCK=JSON.parse(readFileSync(join(ROOT,'registry/compass-source-lock-v1.json'),'utf8'));
const hash=x=>createHash('sha256').update(x).digest('hex');
const fmt=x=>JSON.stringify(x,null,2)+'\n';
const hold=(x,why)=>{if(!x)throw Error('HOLD_COMPASS_EVALUATOR_'+why);};
function runChild(name,args,cwd){
 try{return execFileSync(name,args,{cwd,encoding:'utf8',maxBuffer:12*1024*1024,
  timeout:600000,stdio:['ignore','pipe','pipe']});}
 catch(e){throw Error('HOLD_COMPASS_EVALUATOR_OWNER_'+String(e.stderr||e.message).slice(0,500));}
}
function safeDir(path){
 const p=resolve(path);hold(existsSync(p)&&lstatSync(p).isDirectory()&&!lstatSync(p).isSymbolicLink(),'DIR');
 return realpathSync(p);
}
function git(root,...args){return runChild('git',['--no-replace-objects','-C',root,...args],ROOT).trim();}
export function verifyCompassOwner(path){
 const root=safeDir(path);
 hold(LOCK?.schema==='cannon.compass-source-lock/v1'&&LOCK.repository==='the-static-collective/iron-lung'
  &&LOCK.authority==='NONE'&&LOCK.protocol==='STRICT_DYAD_COMPASS_V1','SOURCE_REGISTRY');
 hold(git(root,'rev-parse','HEAD')===LOCK.commit,'COMMIT');
 hold(git(root,'remote','get-url','origin').replace(/\.git$/,'')==='https://github.com/'+LOCK.repository,'ORIGIN');
 const changes=git(root,'status','--porcelain','--untracked-files=normal').split('\n').filter(Boolean);
 hold(changes.every(x=>x==='?? node_modules/'),'WORKTREE_DIRTY');
 for(const [name,blob] of Object.entries(LOCK.files)){
  hold(git(root,'rev-parse','HEAD:'+name)===blob,'OWNER_BLOB_'+name);
  const bytes=readFileSync(join(root,name));
  const checksum=createHash('sha1').update('blob '+bytes.length+'\0').update(bytes).digest('hex');
  hold(checksum===blob&&realpathSync(join(root,name))===join(root,name),'OWNER_FILE_'+name);
 }
 return {schema:'cannon.compass-owner-observation/v1',
  source:LOCK.repository,commit:LOCK.commit,model:LOCK.model,authority:'NONE'};
}
const tok=t=>t.toLowerCase().match(/[a-z0-9][a-z0-9_-]*/g)||[];
const norm=t=>t.trim().toLowerCase().replace(/\s+/g,' ');
function ratio(a,b){
 const x=new Set(tok(a)),y=new Set(tok(b));if(!x.size)return 0;
 let found=0;for(const n of x)if(y.has(n))found++;
 return Number((found/x.size).toFixed(4));
}
function measures(steps,source,carded){
 const text=steps.map(x=>carded?x.response:x.candidateText);
 const prompt=carded?steps.map(x=>x.card):[];
 const noAnswer=text.filter(x=>/^(no proposal|none|no action is required|unknown|no invention ancestry)\.?$/i.test(x.trim())).length;
 const distinct=new Set(text.map(norm)).size;
 const literalEcho=text.filter((x,i)=>ratio(x,carded?prompt[i]:source)>.72).length;
 const commonLongLines=carded?prompt.flatMap(x=>x.split('\n')).filter(x=>tok(x).length>3).length:null;
 const rows=carded?prompt.reduce((n,c)=>n+c.split('\n').length,0):null;
 const minWords=carded?prompt.flatMap(c=>c.split('\n')).filter(l=>tok(l).length<2).length:null;
 const outputDyadLines=text.reduce((n,t)=>n+t.split('\n').filter(l=>tok(l).length>=2&&tok(l).length<=3).length,0);
 const allOutputLines=text.reduce((n,t)=>n+t.split('\n').length,0);
 return {calls:steps.length,distinctResponses:distinct,identicalRepeats:text.length-distinct,
  noAnswerPatternCount:noAnswer,highLexicalPromptEchoCount:literalEcho,
  submittedCardLineCount:rows,cardLinesOverThreeWords:commonLongLines,
  cardLinesUnderTwoWords:minWords,
  modelResponseDyadLineRatio:Number((outputDyadLines/Math.max(allOutputLines,1)).toFixed(4)),
  meanResponseWordCount:Number((text.reduce((a,b)=>a+tok(b).length,0)/text.length).toFixed(2)),
  provesSemanticNovelty:false,provesWorkingAdapter:false};
}
export function evaluateComparison(packet){
 hold(packet?.schema==='iron-lung/compass-comparison/v1'&&packet.result==='PROPOSALS_ONLY'
  &&packet.humanApproval===false&&packet.fieldSelection===null,'UNVERIFIED_COMPARISON');
 const {comparisonSha256,...core}=packet;
 hold(comparisonSha256===hash(JSON.stringify(core)),'COMPARISON_DIGEST');
 const a=packet.baseline,b=packet.dyadNine,c=packet.dyadTwentySeven;
 hold(a?.steps?.length===9&&b?.steps?.length===9&&c?.steps?.length===27
  &&packet.requestCounts?.total===45&&packet.requestCounts.equalBudget===9,'BUDGETS');
 hold(packet.provider?.model===LOCK.model.name&&packet.provider.revision===LOCK.model.revision
  ||packet.provider?.kind==='deterministic-fixture','MODEL_ID');
 hold(a.source.rawTextSha256===b.source.rawTextSha256&&b.source.rawTextSha256===c.source.rawTextSha256
  &&b.source.braidSha256===c.source.braidSha256
  &&a.source.braidSha256===b.source.braidSha256,'SOURCE_DIFFERENCE');
 const views={
  proseNine:measures(a.steps,c.source.rawText,false),
  compassNine:measures(b.steps,c.source.rawText,true),
  compassMicroTwentySeven:measures(c.steps,c.source.rawText,true)
 };
 hold(views.compassNine.cardLinesOverThreeWords===0
  &&views.compassNine.cardLinesUnderTwoWords===0
  &&views.compassMicroTwentySeven.cardLinesOverThreeWords===0
  &&views.compassMicroTwentySeven.cardLinesUnderTwoWords===0,'NOT_DYADS');
 const coreReport={schema:'cannon.compass-evaluation/v1',sourceOwner:LOCK.repository,
  sourceCommit:LOCK.commit,model:packet.provider,comparisonSha256,
  scoreStatus:'LEXICAL_DIAGNOSTICS_NOT_QUALITY_PROOF',
  equalInferenceBudget:{prose:9,compass:9},
  exploratoryMicroBudget:{compass:27,confoundedByAdditionalCalls:true},
  controls:{sameBraid:true,sameSource:true,sameModel:true,
   generatedAuthority:false,modelSelectedRoute:false,semanticOutcomeVerified:false,
   humanReviewRequired:true},
  views,operatorRecommendation:'INSPECT_RAW_RESPONSES_NO_AUTOMATIC_WINNER',
  realWorldActions:0,autoPromotedCapabilities:0};
 return {...coreReport,reportSha256:hash(fmt(coreReport))};
}
const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;')
 .replaceAll('>','&gt;').replaceAll('"','&quot;');
export function reviewHTML(packet,report){
 const rows=[];
 for(let i=0;i<9;i++){
  const a=packet.baseline.steps[i],b=packet.dyadNine.steps[i];
  rows.push('<tr><td>'+i+'</td><td><pre>'+escape(a.candidateText)+'</pre></td>'+
   '<td><pre>'+escape(b.card)+'</pre><pre>'+escape(b.response)+'</pre></td></tr>');
 }
 const micro=packet.dyadTwentySeven.steps.map((s,i)=>
  '<details><summary>'+escape(i+' / '+s.phase+' / '+s.focus)+'</summary><pre>'+
   escape(s.card)+'</pre><pre>'+escape(s.response)+'</pre></details>').join('\n');
 return '<!doctype html><html lang="en"><meta charset="utf-8">'+
  '<title>INSPAND-007 Compass Review — Held</title>'+
  '<h1>Golden Compass — two-word questions</h1>'+
  '<p>EXPERIMENT ONLY. Generated answers are not facts, permissions or executable software.</p>'+
  '<p>Baseline vs Compass: nine model calls each. Microquestions: 27 calls, not an equal-budget comparison.</p>'+
  '<p>Evidence receipt: <code>'+escape(report.reportSha256)+'</code></p>'+
  '<table border="1"><caption>Equal-budget model responses</caption><thead><tr>'+
  '<th>Step</th><th>Original prose response</th><th>Dyad card and response</th>'+
  '</tr></thead><tbody>'+rows.join('\n')+'</tbody></table>'+
  '<h2>Exploratory 27 microquestions</h2>'+micro+'</html>\n';
}
function parse(argv){
 const [mode,...tail]=argv;hold(['inspect','build','verify'].includes(mode)&&tail.length%2===0,'USAGE');
 const opts={};for(let i=0;i<tail.length;i+=2){
  const k=tail[i],v=tail[i+1];hold(['--lung','--provider','--source','--out','--authorize'].includes(k)
   &&v&&!Object.hasOwn(opts,k),'FLAGS');opts[k]=v;
 }
 hold(opts['--lung'],'SOURCE_REQUIRED');
 if(mode==='inspect')hold(Object.keys(opts).length===1,'READ_ONLY');
 else {
  for(const x of ['--provider','--source','--out'])hold(opts[x],'MISSING_'+x);
  hold(['fixture','flan'].includes(opts['--provider']),'PROVIDER');
  hold(mode==='build'?opts['--authorize']==='SYNTHETIC_TEST_ONLY':!opts['--authorize'],'AUTHORIZE');
 }
 return {mode,opts};
}
export function run(argv){
 const {mode,opts}=parse(argv);
 const owner=verifyCompassOwner(opts['--lung']);
 if(mode==='inspect')return owner;
 const lung=safeDir(opts['--lung']),source=resolve(opts['--source']);
 hold(existsSync(source)&&lstatSync(source).isFile()&&!lstatSync(source).isSymbolicLink(),'SOURCE_INPUT');
 const out=resolve(opts['--out']),parent=safeDir(dirname(out));
 hold(out===join(parent,basename(out)),'OUT_PARENT');
 hold(mode==='build'?!existsSync(out):existsSync(out)&&lstatSync(out).isDirectory(),'OUT_STATE');
 const tmp=mkdtempSync(join(parent,'.compass-review-'));
 try {
  const target=mode==='build'?join(tmp,'packet'):out;
  if(mode==='build')mkdirSync(target);
  const text=runChild('npm',['run','--silent','compass-lab','--','compare',
   '--provider',opts['--provider'],'--source',source],lung);
  const packet=JSON.parse(text);
  const fromOwner=join(tmp,'owner.json');
  writeFileSync(fromOwner,fmt(packet),{flag:'wx'});
  const nativeResult=JSON.parse(runChild('npm',['run','--silent','compass-lab','--','verify',
   '--file',fromOwner],lung));
  hold(nativeResult.status==='COMPASS_PACKET_VERIFIED'
   &&nativeResult.comparisonSha256===packet.comparisonSha256,'OWNER_VERIFICATION');
  const evaluation=evaluateComparison(packet),html=reviewHTML(packet,evaluation);
  const files={'comparison.json':packet,'evaluation.json':evaluation,
   'original-owner.json':owner,'review.html':html};
  for(const [file,payload] of Object.entries(files)){
   const bytes=typeof payload==='string'?payload:fmt(payload);
   if(mode==='build')writeFileSync(join(target,file),bytes,{flag:'wx'});
   else hold(readFileSync(join(target,file),'utf8')===bytes,'REPLAY_'+file);
  }
  if(mode==='build')renameSync(target,out);
  return {status:mode==='build'?'COMPASS_REVIEW_HELD':'COMPASS_COLD_REPLAY_VERIFIED',
   ownerCommit:owner.commit,provider:opts['--provider'],equalBudgetRequests:9,
   exploratoryRequests:27,totalRequests:45,reportSha256:evaluation.reportSha256,
   automaticCapabilities:0};
 }finally{rmSync(tmp,{recursive:true,force:true});}
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){
 try{console.log(fmt(run(process.argv.slice(2))))}
 catch(e){console.error(String(e.message||e).slice(0,1200));process.exitCode=2}
}
